function UIActivityPaySignEntryNode:RefreshContent(isForce)
    isForce = checkBool(isForce)
    if not isForce then
        local titleImgUrl = checkString(self.activityDojo.titleImage)

        local confDefines = checkTable(self.data)
        KTool.SetActive(self.TextPlayExplain, checkInt(confDefines.ruleId) ~= 0)

