function UIActivityPaySignEntryNode:UpdateRoleInfo()
    local singlePanelConf = self.data
    if not singlePanelConf or next(singlePanelConf) == nil then
        return
    end
    local goodsType = GoodsUtils.GetIdType(singlePanelConf.skinId)
    local isCardOrSkin = goodsType == Constants.IDType.CharacterCard or goodsType == Constants.IDType.CardSkin
    KTool.SetActive(self.BossDrawingNode, isCardOrSkin)
    KTool.SetActive(self.BtnRoleNameNode, isCardOrSkin)

    if checkInt(singlePanelConf.skinId) ~= 0 then
        local skinId = checkNumber(singlePanelConf.skinId)
        if goodsType == Constants.IDType.CardSkin then
            local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(singlePanelConf.skinId)
            skinId = checkNumber(skinVo.skinId)
        end
        self.BossDrawingNode.gameObject:EnsureComponent(typeof(CS.Game.Native.Common.DrawingNode)):Execute(checkNumber(skinId), -1, -1, "hdCardDrawing")
        --KTool.SetActive(self.ImgRole, true)
        --CfUtils.FillRoleImage(self.ImgRole, singlePanelConf.skinId, Vector2(382, 242))
    end

    if isCardOrSkin then
        KTool.SetActive(self.BtnRoleNameNode, true)
        ---@type CommonBtnRoleNameNode
        local env = CfUtils.GetLuaScr(self.BtnRoleNameNode, "Game.UI.Common.CommonBtnRoleNameNode")
        if env then
            env:RefreshSelf(singlePanelConf.skinId, nil, function()
                KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID, self.activityDojo.id)
            end, true)
        end
    elseif not string.isEmpty(self.data.rewardPicture) then
        local rewardImage = self.BtnRoleNameNode.transform.parent:Find("ImgReward")
        if rewardImage then
            CfUtils.SetActive(rewardImage, true)
            CfUtils.FillWebRawImage(rewardImage, self.data.rewardPicture)
        end
    end
end

function UIActivityPaySignEntryNode:DrawRequest(rewardsId)
    GameUtils.Request("activity2/receivePaidCheckinRewards",
            { activityUuid = checkInt(self.activityDojo.id), rewardId = checkInt(rewardsId) },
            function(request, response)
                if checkInt(response.errCode) == 0 then
                    local data = response.data
                    GoodsUtils.DrawRewards(checkTable(data.rewards), true)
                    UIModule.OpenDialog(
                            {
                                id = Constants.UITypeIds.UICommonRewardPop,
                                parameters = { rewards = data.rewards }
                            }
                    )
                    self:SetSignStatusById(rewardsId)
                    self:RefreshContent()
                end
            end
    )
end

function UIActivityPaySignEntryNode:FindCurrentSignId()
    local currentId = nil
    local singleSignConf = self.data.rewards
    for index = 1, #singleSignConf do
        local itemSignData = singleSignConf[index]
        if checkInt(itemSignData.status) == Constants.GetStatus.Not then
            currentId = index == 1 and 1 or index - 1
            break
        end
    end
    if not currentId then
        currentId = #singleSignConf
    end
    return currentId
end

function UIActivityPaySignEntryNode:HasSign()
    ---@type PlayerComponent
    local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local curDate = playerComp:GetPlayerDojo():GetServerTimeWithTimeZone()
    local endTime = checkNumber(self.activityDojo.endTime)
    local leftTime = endTime - curDate
    local singleSignConf = self.data.rewards
    local hasSign = -1
    for index = 1, #singleSignConf do
        local itemSignData = singleSignConf[index]
        if checkInt(itemSignData.status) == Constants.GetStatus.Can and leftTime > 0 then
            hasSign = 0
            break
        end
    end
    return hasSign
end

function UIActivityPaySignEntryNode:SetSignStatusById(id)
    for index = 1, #self.data.rewards do
        if self.data.rewards[index].rewardId == id then
            self.data.rewards[index].status = Constants.GetStatus.Has
            break
        end
    end
end

